window.BankingAPI = {
  // Cálculo de cuota fija con sistema francés
  simulateLoan: function(monto, meses, tna) {
    tna = tna || 0.48;
    var r = tna / 12;
    var cuota = (monto * r) / (1 - Math.pow(1 + r, -meses));
    return {
      monto: monto,
      meses: meses,
      cuotaMensual: Math.round(cuota),
      totalAPagar: Math.round(cuota * meses)
    };
  },
  // Verificación de CBU/CVU bancario (22 dígitos)
  validateCBU: function(cbu) {
    return /^\\d{22}$/.test(cbu);
  }
};

